const SOURCE_CONFIG = {
  reddit:  { numResults: 12 },
  quora:   { numResults: 8 },
  forums:  { numResults: 10 },
  youtube: { numResults: 6 }
};

const input = $input.first().json;
const body = (input && typeof input.body === 'object' && input.body !== null) ? input.body : input;

const keyword = String(body.keyword || '').trim();
if (!keyword) throw new Error('A keyword is required.');

const requested = Array.isArray(body.sources) && body.sources.length
  ? body.sources.map(s => String(s).toLowerCase().trim())
  : ['reddit', 'quora', 'forums', 'youtube'];
const sources = requested.filter(s => SOURCE_CONFIG[s]);
if (!sources.length) throw new Error('At least one community source must be enabled (reddit / quora / forums / youtube).');

return [{
  json: {
    keyword,
    location: String(body.location || 'United States').trim(),
    language: String(body.language || 'en').trim(),
    device: String(body.device || 'desktop').trim(),
    industry: String(body.industry || '').trim(),
    sources,
    enabled: {
      reddit: sources.includes('reddit'),
      quora: sources.includes('quora'),
      forums: sources.includes('forums'),
      youtube: sources.includes('youtube')
    },
    num_results: {
      reddit: SOURCE_CONFIG.reddit.numResults,
      quora: SOURCE_CONFIG.quora.numResults,
      forums: SOURCE_CONFIG.forums.numResults,
      youtube: SOURCE_CONFIG.youtube.numResults
    },
    requested_at: body.requested_at || new Date().toISOString()
  }
}];

const resp = $input.first().json || {};
const taskResult = resp.tasks && resp.tasks[0] && resp.tasks[0].result && resp.tasks[0].result[0];
if (!taskResult) return [{ json: { source: 'paa', items: [] } }];

const items = taskResult.items || [];
const paaItem = items.find(i => i.type === 'people_also_ask');
if (!paaItem || !Array.isArray(paaItem.items)) return [{ json: { source: 'paa', items: [] } }];

const paa = paaItem.items.slice(0, 10).map(q => {
  const expanded = Array.isArray(q.expanded_element) && q.expanded_element[0] ? q.expanded_element[0] : null;
  return {
    question: q.title || '',
    answer_snippet: expanded ? (expanded.description || expanded.featured_title || '') : '',
    source_url: expanded ? (expanded.url || '') : '',
    source_domain: expanded ? (expanded.domain || '') : ''
  };
}).filter(q => q.question);

return [{ json: { source: 'paa', items: paa } }];

const enabled = $('Normalize Input').first().json.enabled.reddit;
if (!enabled) return [{ json: { source: 'reddit', items: [] } }];
const resp = $input.first().json || {};
const raw = Array.isArray(resp.results) ? resp.results : [];
const items = raw.map(r => ({
  id: r.id,
  url: r.url,
  title: r.title,
  score: r.score,
  publishedDate: r.publishedDate,
  text: r.text || '',
  highlights: Array.isArray(r.highlights) ? r.highlights : []
}));
return [{ json: { source: 'reddit', items } }];

const enabled = $('Normalize Input').first().json.enabled.quora;
if (!enabled) return [{ json: { source: 'quora', items: [] } }];
const resp = $input.first().json || {};
const raw = Array.isArray(resp.results) ? resp.results : [];
const items = raw.map(r => ({
  id: r.id, url: r.url, title: r.title, score: r.score,
  publishedDate: r.publishedDate,
  text: r.text || '',
  highlights: Array.isArray(r.highlights) ? r.highlights : []
}));
return [{ json: { source: 'quora', items } }];

const enabled = $('Normalize Input').first().json.enabled.forums;
if (!enabled) return [{ json: { source: 'forums', items: [] } }];
const resp = $input.first().json || {};
const raw = Array.isArray(resp.results) ? resp.results : [];
const items = raw.map(r => ({
  id: r.id, url: r.url, title: r.title, score: r.score,
  publishedDate: r.publishedDate,
  text: r.text || '',
  highlights: Array.isArray(r.highlights) ? r.highlights : []
}));
return [{ json: { source: 'forums', items } }];

const enabled = $('Normalize Input').first().json.enabled.youtube;
if (!enabled) return [{ json: { source: 'youtube', items: [] } }];
const resp = $input.first().json || {};
const raw = Array.isArray(resp.results) ? resp.results : [];
const items = raw.map(r => ({
  id: r.id, url: r.url, title: r.title, score: r.score,
  publishedDate: r.publishedDate,
  text: r.text || '',
  highlights: Array.isArray(r.highlights) ? r.highlights : []
}));
return [{ json: { source: 'youtube', items } }];

// Stitch the 5 lanes back into a single payload the LLM can consume.
const inputs = $('Normalize Input').first().json;
const lanes = $input.all().map(it => it.json);
const bySource = new Map(lanes.map(l => [l.source, l.items || []]));

const paa = bySource.get('paa') || [];
const exaBundles = [
  { source: 'reddit',  results: bySource.get('reddit')  || [] },
  { source: 'quora',   results: bySource.get('quora')   || [] },
  { source: 'forums',  results: bySource.get('forums')  || [] },
  { source: 'youtube', results: bySource.get('youtube') || [] }
].filter(b => inputs.enabled[b.source]);

function safeHost(url) { try { return new URL(url).host.replace(/^www\./, ''); } catch { return ''; } }

function buildPaaBlock(paa) {
  if (!paa.length) return '';
  const rows = paa.map((q, idx) => {
    const id = 'PAA' + (idx + 1);
    return [
      '[' + id + '] ' + q.question,
      q.answer_snippet ? 'Snippet: ' + String(q.answer_snippet).replace(/\s+/g, ' ').trim().slice(0, 320) : '',
      q.source_url ? 'Source: ' + q.source_url : ''
    ].filter(Boolean).join('\n');
  });
  return '=== GOOGLE PEOPLE ALSO ASK (' + paa.length + ' items) ===\n' + rows.join('\n\n');
}

function buildEvidenceBlock(source, items) {
  if (!items.length) return '';
  const rows = items.slice(0, 12).map((it, idx) => {
    const id = source[0].toUpperCase() + (idx + 1);
    const title = (it.title || '').replace(/\s+/g, ' ').trim().slice(0, 200);
    const highlights = Array.isArray(it.highlights)
      ? it.highlights.slice(0, 3).map(h => '  \u00b7 ' + String(h).replace(/\s+/g, ' ').trim().slice(0, 320)).join('\n')
      : '';
    const textSample = it.text ? String(it.text).replace(/\s+/g, ' ').trim().slice(0, 600) : '';
    return [
      '[' + id + '] ' + title,
      it.url ? 'URL: ' + it.url : '',
      highlights ? 'Top passages:\n' + highlights : '',
      textSample ? 'Body excerpt: ' + textSample : ''
    ].filter(Boolean).join('\n');
  });
  return '=== ' + source.toUpperCase() + ' (' + items.length + ' items) ===\n' + rows.join('\n\n');
}

const sourceBlocks = exaBundles.map(b => buildEvidenceBlock(b.source, b.results)).filter(Boolean);
const totalEvidence = paa.length + exaBundles.reduce((s, b) => s + b.results.length, 0);

// Build citation lookup for the dashboard.
const citations = {};
paa.forEach((q, i) => {
  citations['PAA' + (i + 1)] = { kind: 'paa', label: q.question, url: q.source_url || '', domain: q.source_domain || '' };
});
for (const { source, results } of exaBundles) {
  const prefix = source[0].toUpperCase();
  results.slice(0, 12).forEach((it, i) => {
    citations[prefix + (i + 1)] = { kind: source, label: it.title || '', url: it.url || '', domain: it.url ? safeHost(it.url) : '' };
  });
}

const source_counts = exaBundles.map(b => ({ source: b.source, count: b.results.length, error: null }));

return [{
  json: {
    ...inputs,
    paa,
    exa_bundles: exaBundles,
    source_blocks: sourceBlocks,
    paa_block: buildPaaBlock(paa),
    total_evidence: totalEvidence,
    citations,
    source_counts
  }
}];

const inp = $input.first().json;
return [{
  json: {
    request: { keyword: inp.keyword, location: inp.location, language: inp.language, sources: inp.sources },
    summary: 'No evidence returned by any source. Try a broader keyword or check API connectivity.',
    clusters: [],
    unclustered_questions: [],
    paa: [],
    source_counts: inp.source_counts,
    citations: {},
    generated_at: new Date().toISOString()
  }
}];

const upstream = $('Build LLM Payload').first().json;
const response = $input.first().json;

if (response && response.error) {
  return [{ json: { error: 'OpenRouter error: ' + (response.error.message || response.error.code || JSON.stringify(response.error)), raw: response.error } }];
}

const text = response && response.choices && response.choices[0] && response.choices[0].message && response.choices[0].message.content;
if (!text) {
  return [{ json: { error: 'No content in OpenRouter response', raw: response } }];
}

let parsed;
try { parsed = JSON.parse(text); }
catch (e) {
  const cleaned = text.replace(/^```json\s*/i, '').replace(/```\s*$/, '').trim();
  try { parsed = JSON.parse(cleaned); }
  catch (e2) { return [{ json: { error: 'Failed to parse JSON from model', raw_text: text } }]; }
}

if (Array.isArray(parsed.clusters) && parsed.clusters.length) {
  const total = parsed.clusters.reduce((s, c) => s + (Number(c.weight) || 0), 0);
  if (total > 0 && Math.abs(total - 100) > 5) {
    parsed.clusters = parsed.clusters.map(c => ({ ...c, weight: Math.round((Number(c.weight) || 0) * 100 / total) }));
  }
  parsed.clusters.sort((a, b) => (Number(b.weight) || 0) - (Number(a.weight) || 0));
}
parsed.keyword = parsed.keyword || upstream.keyword;

return [{
  json: {
    request: {
      keyword: upstream.keyword,
      location: upstream.location,
      language: upstream.language,
      device: upstream.device,
      industry: upstream.industry,
      sources: upstream.sources
    },
    summary: parsed.summary || '',
    clusters: Array.isArray(parsed.clusters) ? parsed.clusters : [],
    unclustered_questions: Array.isArray(parsed.unclustered_questions) ? parsed.unclustered_questions : [],
    notes: parsed.notes || '',
    paa: upstream.paa,
    source_counts: upstream.source_counts,
    citations: upstream.citations,
    generated_at: new Date().toISOString()
  }
}];
